import {PianoPlayer,arrangeForGuitar} from './audio.js';

const $=s=>document.querySelector(s);
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const catalog=[
 {id:'moonlight',title:'月光奏鸣曲',artist:'Ludwig van Beethoven',category:'classical',art:'moon',caption:'Moonlight',tag:'古典 · 第一乐章',source:'https://github.com/KiyoEditz/Maestro'},
 {id:'cherry',title:'樱花草',artist:'Sweety · 李天龙',category:'pop',art:'flower',caption:'Primrose',tag:'流行 · 钢琴改编',source:'https://www.everyonepiano.cn/Music-2003.html'},
 {id:'river',title:'River Flows in You',artist:'Yiruma · 李闰珉',category:'pop',art:'river',caption:'River flows',tag:'流行 · 治愈钢琴',source:'https://github.com/KiyoEditz/Maestro'},
 {id:'elise',title:'致爱丽丝',artist:'Ludwig van Beethoven',category:'classical',art:'elise',caption:'Für Elise',tag:'古典 · 钢琴独奏',source:'https://github.com/fabiomigueldp/pianomancer'},
 {id:'canon',title:'卡农',artist:'Johann Pachelbel',category:'classical',art:'canon',caption:'Canon in C',tag:'古典 · C 大调改编',source:'https://github.com/MAraragi/MusicalScoreRecognition'},
 {id:'golden',title:'golden hour',artist:'JVKE',category:'pop',art:'golden',caption:'Golden hour',tag:'流行 · 钢琴改编',source:'https://github.com/KiyoEditz/Maestro'}
];
const format=seconds=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
let instrument='piano',boundKey='',chord='C';
let current=0,filter='all',shuffle=false,loop=1,busy=false,desiredPlayback=false,requestId=0,toastTimer,room=null,previousVolume=.65;
let favorites=[];try{favorites=JSON.parse(localStorage.getItem('nocturne-favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{}
const player=new PianoPlayer(()=>{if(loop===2){player.start();setPlaying(true);return;}if(!shuffle&&current===catalog.length-1&&loop===0){desiredPlayback=false;setPlaying(false);return;}selectTrack(nextIndex(1),true);});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function renderTracks(){const tracks=catalog.filter(t=>filter==='all'||(filter==='favorites'?favorites.includes(t.id):t.category===filter));$('#track-list').innerHTML=tracks.length?tracks.map(t=>`<button class="track-card ${catalog[current]===t?'selected':''}" data-track="${t.id}" aria-label="播放${t.title}" aria-pressed="${catalog[current]===t}"><span class="album art-${t.art}"><span class="album-text">${t.caption}</span></span><span class="track-meta"><span class="track-name">${t.title}</span><span class="track-composer">${t.artist}</span><span class="track-tag">${instrument==='guitar'?t.tag.replace('钢琴','吉他'):t.tag}</span><span class="track-length">${t.duration?format(t.duration):'—'}</span></span><span class="track-card-play">${icon(catalog[current]===t&&player.playing?'pause':'play')}</span></button>`).join(''):'<div class="empty-list">把喜欢的旋律收藏在这里。点击播放器上的 ♡，留住这一首。</div>';}
function renderFavorite(){const liked=favorites.includes(catalog[current].id);$('#favorite').classList.toggle('active',liked);$('#favorite').setAttribute('aria-label',liked?'取消收藏当前曲目':'收藏当前曲目');$('#favorite').setAttribute('aria-pressed',liked);}
function setPlaying(playing){document.body.classList.toggle('playing',playing);$('#play').innerHTML=icon(playing?'pause':'play');$('#play').setAttribute('aria-label',playing?'暂停':'播放');$('#start').querySelector('svg use').setAttribute('href','#i-'+(playing?'pause':'play'));$('#start-label').textContent=playing?'让旋律停留':player.offset>0?'继续这一刻':'开启这一刻';$('#scene-status').textContent=playing?'正在演奏 · '+catalog[current].title:player.offset>0?'让音乐歇一会儿':'静候一场演奏';$('#sound-hint').textContent=playing?(instrument==='guitar'?'木吉他实录音色 · 自动连续演奏':'钢琴实录音色 · 自动连续演奏'):'轻点开启声音 · 随后自动连续演奏';renderTracks();}
function updateCurrent(){const t=catalog[current];$('#track-title').textContent=t.title;$('#track-artist').textContent=t.artist;$('#player-art').className='album-small art-'+t.art;$('#duration').textContent=format(t.duration||0);$('#elapsed').textContent='0:00';$('#progress').value=0;$('#progress').style.setProperty('--fill','0%');document.title=t.title+' — NOCTURNE · 夜曲';renderTracks();renderFavorite();if('mediaSession'in navigator&&typeof MediaMetadata!=='undefined')navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:'NOCTURNE · 夜曲'});}
const musicReady=Promise.all(catalog.map(async t=>{const r=await fetch('./assets/music/'+t.id+'.json');if(!r.ok)throw new Error('曲谱加载失败，请刷新页面重试');const d=await r.json();if(!d.notes?.length||!Number.isFinite(d.duration))throw new Error('曲谱数据无效');Object.assign(t,d);})).then(()=>{syncTrack();updateCurrent();}).catch(e=>{toast(e.message);$('#sound-hint').textContent=e.message;throw e;});
musicReady.catch(()=>{});
async function startPlayback(){if(busy)return;busy=true;desiredPlayback=true;const id=++requestId;$('#start-label').textContent='正在唤醒琴声';$('#play').setAttribute('aria-busy','true');try{const ready=player.init();await Promise.all([musicReady,ready]);if(id!==requestId||!desiredPlayback)return;if(boundKey!==instrument+current)syncTrack();player.start();setPlaying(player.playing);}catch(e){if(id===requestId){desiredPlayback=false;toast(e.message||'声音加载失败，请再试一次');setPlaying(false);}}finally{if(id===requestId){busy=false;$('#play').removeAttribute('aria-busy');}}}
function pausePlayback(){requestId++;desiredPlayback=false;busy=false;$('#play').removeAttribute('aria-busy');player.pause();room?.setNotes([]);setPlaying(false);}
function togglePlayback(){if(player.playing||busy){pausePlayback();return;}startPlayback();}
async function selectTrack(index,autoplay=true){const id=++requestId;desiredPlayback=autoplay;player.pause();current=index;updateCurrent();setPlaying(false);try{await musicReady;if(id!==requestId)return;syncTrack();if(autoplay){busy=false;await startPlayback();}}catch(e){toast(e.message);}}
function nextIndex(dir){if(shuffle){const options=catalog.map((_,i)=>i).filter(i=>i!==current);return options[Math.floor(Math.random()*options.length)];}return (current+dir+catalog.length)%catalog.length;}
$('#play').addEventListener('click',togglePlayback);$('#start').addEventListener('click',togglePlayback);
$('#next').addEventListener('click',()=>selectTrack(nextIndex(1)));$('#previous').addEventListener('click',()=>{if(player.position()>3){player.seek(0);toast('从头聆听这一首');}else selectTrack(nextIndex(-1));});
$('#track-list').addEventListener('click',e=>{const card=e.target.closest('[data-track]');if(!card)return;const index=catalog.findIndex(t=>t.id===card.dataset.track);if(index===current)togglePlayback();else selectTrack(index);});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',String(b===button));});renderTracks();}));
$('#favorite').addEventListener('click',()=>{const id=catalog[current].id;const liked=favorites.includes(id);favorites=liked?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('nocturne-favorites',JSON.stringify(favorites));}catch{}renderFavorite();if(filter==='favorites')renderTracks();toast(liked?'已从收藏中移除':'已收藏，让喜欢的旋律常在');});
$('#shuffle').addEventListener('click',()=>{shuffle=!shuffle;$('#shuffle').classList.toggle('enabled',shuffle);$('#shuffle').setAttribute('aria-pressed',String(shuffle));toast(shuffle?'随机播放已开启':'按曲目顺序播放');});
$('#loop').addEventListener('click',()=>{loop=(loop+1)%3;$('#loop').classList.toggle('enabled',loop>0);$('#loop').classList.toggle('repeat-one',loop===2);const text=['播完列表后停止','列表循环','单曲循环'][loop];$('#loop').setAttribute('aria-label',text);$('#loop').setAttribute('title',text);$('#loop').setAttribute('aria-pressed',String(loop>0));toast(text);});
$('#progress').addEventListener('input',e=>{player.seek(Number(e.target.value)/100*player.duration);updateProgress();});
function setVolume(v){player.setVolume(v);$('#volume').value=Math.round(v*100);$('#volume').style.setProperty('--fill',v*100+'%');$('#mute').innerHTML=icon(v===0?'mute':'volume');$('#mute').setAttribute('aria-label',v===0?'取消静音':'静音');}
$('#volume').addEventListener('input',e=>setVolume(Number(e.target.value)/100));$('#mute').addEventListener('click',()=>{if(player.volume){previousVolume=player.volume;setVolume(0);}else setVolume(previousVolume||.65);});
let night=false;try{night=localStorage.getItem('nocturne-night')==='true';}catch{}
function applyTheme(){document.body.classList.toggle('night',night);$('#theme').innerHTML=icon(night?'sun':'moon');$('#theme').setAttribute('aria-label',night?'切换白昼':'切换夜色');room?.setTheme(night);document.querySelector('meta[name="theme-color"]').content=night?'#202622':'#eeece6';}
$('#theme').addEventListener('click',()=>{night=!night;applyTheme();try{localStorage.setItem('nocturne-night',String(night));}catch{}});applyTheme();
function immersive(value){document.body.classList.toggle('immersed',value);$('#immersive').setAttribute('aria-pressed',String(value));requestAnimationFrame(()=>room?.resize());if(value)toast('已进入沉浸模式 · 右上角可退出');}
$('#immersive').addEventListener('click',()=>immersive(true));$('#exit-immersive').addEventListener('click',()=>immersive(false));
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',b===x));room?.setView(b.dataset.view);}));
$('#about').addEventListener('click',()=>$('#about-dialog').showModal());$('#close-about').addEventListener('click',()=>$('#about-dialog').close());$('#about-dialog').addEventListener('click',e=>{if(e.target===$('#about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#credits').innerHTML='钢琴采样：<a href="https://sfzinstruments.github.io/pianos/salamander/" target="_blank" rel="noopener">Salamander Grand Piano</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a><br>吉他采样：<a href="https://github.com/nbrosowsky/tonejs-instruments" target="_blank" rel="noopener">Tone.js Instruments · Nicholas Brosowsky / University of Iowa · CC BY 3.0</a><br>曲谱来源：'+catalog.map(t=>`<a href="${t.source}" target="_blank" rel="noopener">${t.title}</a>`).join(' · ');
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#about-dialog').open)return;if(instrument==='guitar'&&/^[1-6]$/.test(e.key)){e.preventDefault();playManual(Number(e.key)-1);return;}if(e.target.matches('button,a'))return;if(e.code==='Space'){e.preventDefault();togglePlayback();}if(e.code==='ArrowRight'){e.preventDefault();player.seek(player.position()+5);}if(e.code==='ArrowLeft'){e.preventDefault();player.seek(player.position()-5);}if(e.code==='Escape')immersive(false);});
if('mediaSession'in navigator){for(const [action,handler] of Object.entries({play:startPlayback,pause:pausePlayback,previoustrack:()=>selectTrack(nextIndex(-1)),nexttrack:()=>selectTrack(nextIndex(1)),seekto:e=>player.seek(e.seekTime)}))try{navigator.mediaSession.setActionHandler(action,handler);}catch{}}
function updateProgress(){const pos=player.position();$('#elapsed').textContent=format(pos);if(document.activeElement!==$('#progress'))$('#progress').value=player.duration?pos/player.duration*100:0;$('#progress').style.setProperty('--fill',(player.duration?pos/player.duration*100:0)+'%');room?.setNotes(player.activeNotes());}
setInterval(updateProgress,65);
renderTracks();renderFavorite();
import('./scene.js').then(({createPianoRoom})=>{room=createPianoRoom($('#scene'),()=>{$('#scene-loading').style.opacity='0';},()=>{throw new Error('WebGL is unavailable');});applyTheme();room.setInstrument(instrument);}).catch(()=>{$('#scene-loading').innerHTML='当前设备暂不支持 3D，仍可安心听琴';$('#scene-loading').style.opacity='1';$('#scene-loading').style.left='45%';$('#scene').innerHTML='<div class="piano-fallback" aria-hidden="true">♬</div>';});

function syncTrack(position=0){const t=catalog[current];if(!t.notes)return;if(instrument==='guitar'&&!t.guitarNotes)t.guitarNotes=arrangeForGuitar(t.notes);player.setTrack({...t,notes:instrument==='guitar'?t.guitarNotes:t.notes});if(position)player.seek(position);boundKey=instrument+current;}
function applyInstrumentUI(){const guitar=instrument==='guitar';document.body.classList.toggle('guitar-mode',guitar);document.querySelectorAll('[data-instrument]').forEach(b=>{b.classList.toggle('active',b.dataset.instrument===instrument);b.setAttribute('aria-pressed',String(b.dataset.instrument===instrument));});$('#guitar-playground').hidden=!guitar;$('#room-eyebrow').innerHTML='<span></span> YOUR PRIVATE '+(guitar?'GUITAR':'PIANO')+' ROOM';$('#hero-title').innerHTML=guitar?'拨动，<br>心弦<span class="h1-dot">。</span>':'让时间，<br>慢一拍<span class="h1-dot">。</span>';$('#hero-description').innerHTML=guitar?'让熟悉的旋律，换一种温度。<br>此刻，只有你和六根弦。':'把喧嚣留在门外。<br>此刻，只有你和钢琴。';$('.room-coordinate').innerHTML=guitar?'<span>THE ACOUSTIC No. 02</span><span>6 STRINGS · A THOUSAND STORIES</span>':'<span>THE GRAND No. 01</span><span>88 KEYS · ENDLESS POSSIBILITIES</span>';$('.room').setAttribute('aria-label',guitar?'3D 吉他房':'3D 钢琴房');$('#scene').setAttribute('aria-label',guitar?'可拖动旋转的三维木吉他':'可拖动旋转的三维黑色三角钢琴');$('[data-view="keys"]').textContent=guitar?'指板':'琴键';$('[data-view="above"]').textContent=guitar?'侧影':'俯瞰';$('.drag-hint').innerHTML='拖动探索 3D '+(guitar?'吉他':'琴房')+' <span>↔</span>';$('#library-description').textContent=guitar?'熟悉的旋律，温暖的吉他拨弦。':'熟悉的旋律，全新的钢琴独奏。';$('.audio-label>span').textContent=guitar?'ACOUSTIC GUITAR':'GRAND PIANO';room?.setInstrument(instrument);renderTracks();}
function chooseInstrument(mode){if(mode===instrument)return;const resume=player.playing||desiredPlayback,position=player.position();pausePlayback();instrument=mode;player.setInstrument(mode);syncTrack(position);applyInstrumentUI();setPlaying(false);try{localStorage.setItem('nocturne-instrument',mode);}catch{}if(resume)startPlayback();}
document.querySelectorAll('[data-instrument]').forEach(b=>b.addEventListener('click',()=>chooseInstrument(b.dataset.instrument)));
const chords={C:{notes:[null,48,52,55,60,64],name:'C 大三和弦'},Am:{notes:[null,45,52,57,60,64],name:'Am 小三和弦'},F:{notes:[41,48,53,57,60,65],name:'F 大三和弦'},G:{notes:[43,47,50,55,59,67],name:'G 大三和弦'},D:{notes:[null,null,50,57,62,66],name:'D 大三和弦'},Em:{notes:[40,47,52,55,59,64],name:'Em 小三和弦'}};
document.querySelectorAll('[data-chord]').forEach(b=>b.addEventListener('click',()=>{chord=b.dataset.chord;$('#chord-label').textContent=chords[chord].name;document.querySelectorAll('[data-chord]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
async function playManual(string=null){if(instrument!=='guitar')return;const notes=[...chords[chord].notes];if(string!==null&&notes[string]===null){toast('这个和弦不弹这根弦');return;}if(player.playing||busy)pausePlayback();const id=requestId;try{await player.init('guitar');if(instrument!=='guitar'||id!==requestId)return;if(string===null){player.strum(notes);notes.forEach((n,i)=>{if(n!==null)setTimeout(()=>{if(instrument==='guitar'&&id===requestId)room?.pluck(n,i);},i*35);});}else{player.note(notes[string],player.context.currentTime,2.1,.78);room?.pluck(notes[string],string);}$('#scene-status').textContent='自由试弹 · '+chords[chord].name;}catch(e){toast(e.message||'吉他音色加载失败，请重试');}}
$('#strum').addEventListener('click',()=>playManual());document.querySelectorAll('[data-string]').forEach(b=>b.addEventListener('click',()=>playManual(Number(b.dataset.string))));
try{if(localStorage.getItem('nocturne-instrument')==='guitar')chooseInstrument('guitar');}catch{}

// Browsers that grant autoplay can start immediately; otherwise retain the clear entry button.
musicReady.then(()=>{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const probe=new AC();if(probe.state==='running'){probe.close();startPlayback();}else probe.close();}).catch(()=>{});
